from pathlib import Path
from lesson_authoring import entry as E
M=[['拉丁 mētīrī，分词 mēnsus','测量、量出大小'],['拉丁 mēnsūra → 古法语 mesure → 英语名词 measure','尺寸、分量、衡量的标准']]
MV=[['拉丁 mēnsūra → 晚期拉丁 mēnsūrāre','尺度 → 测量'],['古法语 mesurer → 英语动词 measure','量出尺寸；衡量']]
D=[['拉丁 dis- + mētīrī → dīmētīrī','分开量、量定'],['拉丁 dīmēnsiō → 英语 dimension','测量、范围 → 尺寸、维度、方面']]
I=[['拉丁 in- + mēnsus → immensus','没有被量定的、不可量的'],['法语 immense / 拉丁 immensus → 英语 immense','大得难以丈量 → 极大的']]
C=[['拉丁 com- + mēnsūra / mēnsūrāre','放在一起量、按共同尺度衡量']]
def A(h,a,b):return h+[[a,b]]
W=[
E('measure','英 /ˈmeʒə/；美 /ˈmeʒər/','测量；衡量；尺度；措施','先把尺子贴上去看有多大，再把同一动作搬到成绩、风险和行动上。','名词经古法语 mesure 接拉丁 mēnsūra；动词经 mesurer 接晚期拉丁 mēnsūrāre，两条借入线相通。',M+[['英语 measure 的用法扩展','量大小 → 评估；标准；为达到目的而采取的办法']],'measure a room 是拿工具量；measure success 是判断成功到什么程度。a measure of success 可指一定程度的成功，也可依上下文指衡量成功的指标。take measures 是采取措施，这里的措施是安排出来的行动，不是“拿几把尺子”。','measure the width；measure success by；take measures to do；a measure of。','measurement 偏测量过程或结果；measure 还可表示标准、办法，词义范围更宽。',('Please measure the window before ordering the curtains.','订窗帘前请先量好窗户。'),('We measure success by how much our students improve.','我们按学生进步多少来衡量是否成功。'),('The school took measures to reduce food waste.','学校采取了减少食物浪费的措施。'),sources=['https://www.etymonline.com/word/measure']),
E('measurement','英 /ˈmeʒəmənt/；美 /ˈmeʒərmənt/','测量；测得的数值、尺寸','把“量一量”当成一个过程，或者把量出来的数记下来。','measure + -ment。',A(MV,'英语 measurement','测量这件事；测量得到的结果'),'take a measurement 是测一次或记一个数；take someone’s measurements 常是量做衣服所需的各个尺寸。measurement error 是测量误差，不一定是操作失误。','take a measurement；accurate measurements；measurement error。','measure 可是行动措施；measurement 通常不会表示政策措施。',('Take three measurements and calculate the average.','测三次，然后算出平均值。'),('The tailor wrote down my measurements.','裁缝记下了我的各项尺寸。')),
E('measured','英 /ˈmeʒəd/；美 /ˈmeʒərd/','测得的；审慎的；克制而有分寸的','一条线经过量度，一个回答也可以像量过分寸后才说出口。','measure + -ed；既是过去式、过去分词，也形成形容词。',A(MV,'英语 measured','已经量过的 → 不慌不忙、有控制的'),'a measured value 是实际测得的数；a measured response 则是冷静、审慎的回应。后一个义不要求真拿仪器测，而是把“有尺度”借给说话和做事。','a measured response；a measured tone；the measured distance。','measurable 是能量；measured 是已经量过，或态度克制；两者不能互换。',('The measured distance was slightly shorter than expected.','测得的距离比预想的略短。'),('She answered in a calm, measured tone.','她用冷静、有分寸的语气作答。'),sources=['https://www.merriam-webster.com/dictionary/measured']),
E('measuring','/ˈmeʒərɪŋ/','正在测量；用于测量的','把尺子、量杯等工具正在做的事，直接放进句子或工具名称。','measure 去词尾 e + -ing。',A(MV,'英语 measuring','进行测量；用于量取大小、分量'),'They are measuring 是正在量；a measuring cup 是用来量容量的杯子。measuring 在后一种结构里说明用途，不是说杯子自己正在动作。','a measuring cup；a measuring tape；be measuring。','measured 描述已量过或态度审慎；measuring 描述正在量或测量用途。',('They are measuring the depth of the river.','他们正在测量河水深度。'),('Use a measuring cup to add the milk.','用量杯量取牛奶后加入。')),
E('measurable','/ˈmeʒərəbəl/','可测量的；能看出、能量出的','变化不能只凭“感觉不错”，还得有办法辨认出大小或程度。','古法语 mesurable，接拉丁 mēnsūrābilis；现代可按 measure + -able 理解。',M[:1]+[['拉丁 mēnsūrābilis → 古法语 mesurable → 英语 measurable','可以量度、受度量约束的 → 可测量的']],'measurable progress 通常强调进步有证据可查，不只是印象。它不要求所有指标都用厘米，也可以用时间、比例或事先规定的评分方法来衡量。','measurable progress；measurable impact；a measurable goal。','visible 是看得见；measurable 强调能通过某种尺度判断程度，两者并不相同。',('The new schedule produced a measurable improvement in attendance.','新安排使出勤率出现了可量出的改善。'),('Set a goal with a clear, measurable outcome.','设定一个结果明确、可以衡量的目标。'),sources=['https://www.etymonline.com/word/measurable']),
E('immeasurable','/ɪˈmeʒərəbəl/','无法衡量的；大得难以估量的','尺子或数字装不下它：有时是真的难量，有时是表达分量极大。','否定前缀 im- + measurable；中古英语已有 inmesurable 等拼法。',M[:1]+[['法语 mesurable / 英语 measurable → 中古英语 inmesurable → immeasurable','可测量 → 无法用尺度量定']],'immeasurable gratitude 是感激之深无法说清，通常是表达感情。immeasurable harm 是损害巨大或无法完整量化；它不自动等于数学上的无穷大。','immeasurable value；immeasurable harm；immeasurable gratitude。','immense 通常说非常大；immeasurable 更明确地把“无法量尽”放在前面。',('Her advice was of immeasurable value to me.','她的建议对我有难以估量的价值。'),('The fire caused immeasurable damage to the community.','那场火灾给社区造成了难以估量的损失。'),sources=['https://www.etymonline.com/word/immeasurable']),
E('immeasurably','/ɪˈmeʒərəbli/','无法估量地；极大地','不报一个精确数字，而是强调改善、损失或帮助的程度非常大。','immeasurable + -ly，结尾 -able 变 -ably。',A(M[:1],'英语 measurable → immeasurable → immeasurably','能量 → 难以量尽 → 程度大得难以估量'),'immeasurably better 是好得多得多；help immeasurably 是帮助极大。它经常是有感情色彩的强调，不适合拿来代替实验报告中本来能提供的数值。','immeasurably better；help immeasurably；enrich immeasurably。','immensely 直接强调极大程度；immeasurably 还保留难以量清的感觉。',('The garden looks immeasurably better after a week of work.','忙了一周后，花园的样子好了不知多少。'),('Your support has helped me immeasurably.','你的支持给了我极大的帮助。')),
E('immense','/ɪˈmens/','极大的；巨大的','大到像是拿着尺子也量不到头。','拉丁 in-“不” + mēnsus“量过的”→ immensus；经法语或直接从拉丁借入英语。',I,'immense pressure 可以是巨大压力；immense talent 是极高的才华。现代常用义是程度非常大，并不要求对象实际上无法测量。','immense pressure；immense pleasure；an immense amount。','in- 在 m 前同化为 im-；这里不是“进入”，也不要把 mense 当成英语单词。',('The team worked under immense pressure.','团队在巨大压力下工作。'),('An immense crowd filled the square.','人山人海挤满了广场。'),sources=['https://www.etymonline.com/word/immense']),
E('immensely','/ɪˈmensli/','极其；非常','用“巨大”去放大喜欢、受欢迎、感激等程度。','immense + -ly，保留词尾 e。',A(I,'英语 immensely','以极大的程度'),'enjoy something immensely 是非常喜欢或享受；immensely popular 是极受欢迎。它经常自然地修饰感受，不必每次都生硬译成“巨大地”。','enjoy immensely；immensely popular；immensely grateful。','immensity 是名词“巨大程度”；immensely 是副词，修饰动作或性质。',('I enjoyed the concert immensely.','我非常享受这场音乐会。'),('The book became immensely popular with young readers.','这本书深受年轻读者欢迎。')),
E('immensity','/ɪˈmensəti/','巨大；浩瀚；辽阔','站在海边或任务面前，感受到它到底有多大。','经法语 immensité 接拉丁 immensitās；现代可按 immense + -ity 记忆。',I[:1]+[['拉丁 immensitās → 法语 immensité → 英语 immensity','不可量的广大程度 → 浩瀚、巨大']],'the immensity of the ocean 把注意力放在海的辽阔；the immensity of the task 是任务规模之大。它是性质或程度，不能简单当作 many 的高级替换。','the immensity of space；the immensity of a task。','immense 直接形容东西大；immensity 把“有多大”单独拿出来谈。',('The photograph captures the immensity of the desert.','这张照片展现了沙漠的辽阔。'),('Only then did we understand the immensity of the task.','直到那时，我们才明白任务规模有多大。'),sources=['https://www.etymonline.com/word/immensity']),
E('dimension','/dɪˈmenʃən/，也读 /daɪˈmenʃən/','尺寸；维度；方面','看一只箱子，长、宽、高各量一个方向；看一个问题，也可分不同方面。','拉丁 dis-“分开” + mētīrī“测量”→ dīmētīrī → dīmēnsiō，借入英语。',D,'the dimensions of a box 常是长宽高；the social dimension of a problem 是社会层面。数学中的维度有精确含义，例如平面上的位置通常用两个独立坐标指定。这里 di- 不是“二”，dimension 本身没有规定必须二维。','the dimensions of；a social dimension；add a new dimension。','size 通常笼统说大小；dimension 可以指某个方向的大小，也可以指独立的方面。',('Check the dimensions of the desk before buying it.','买桌子前核对一下它的长宽高。'),('The interview added a personal dimension to the story.','这次访谈给报道增添了个人经历这一层面。'),sources=['https://www.etymonline.com/word/dimension']),
E('dimensional','/dɪˈmenʃənəl/，也读 /daɪˈmenʃənəl/','尺寸的；维度的；量纲的','谈的是物体有多大、空间有几个方向，或物理量由哪些基本量组成。','dimension + -al。',A(D,'英语 dimensional','与尺寸、维度或量纲有关的'),'dimensional accuracy 是尺寸做得准不准；dimensional analysis 是分析量纲，如速度属于长度除以时间。具体是哪种意思，要看工程、数学还是物理语境。','dimensional accuracy；dimensional analysis；dimensional stability。','dimensionless 在物理里说量纲为一；dimensional 不一定说物体是三维。',('The parts were checked for dimensional accuracy.','这些零件经过了尺寸精度检查。'),('Dimensional analysis can reveal an error in the formula.','量纲分析可以发现公式中的一个错误。')),
E('dimensionality','/dɪˌmenʃəˈnæləti/','维度数；维度方面的性质','不用问“它多大”，改问“描述它需要多少个独立方向或变量”。','dimensional + -ity，或按 dimension + -ality 分析。',A(D,'英语 dimensional → dimensionality','有维度的 → 维度数或维度性质'),'在数据分析里，一条记录若由许多特征描述，数据就具有较高维度；reduce dimensionality 是减少描述所需的维度。维度多不等于样本多，十个人也可能各有一百项特征。','reduce dimensionality；high dimensionality；the dimensionality of the data。','dimension 可指单个方面；dimensionality 通常着眼于整体有多少维，不能与体积大小混为一谈。',('The method reduces the dimensionality of the data.','这种方法降低了数据的维度。'),('Increasing the number of features changes the dimensionality.','增加特征数量会改变维度数。')),
E('dimensionless','/dɪˈmenʃənləs/','无量纲的；量纲为一的','同类量相除，米和米抵消，剩下纯粹的比例。','dimension + -less；物理中 dimension 指量纲。',A(D,'英语 dimensionless','不带长度、时间等基本量纲的组合'),'若模型与实物的长度比为 1:100，这个比例没有长度量纲。无量纲不等于数值为零，也不能一概说没有任何单位名称：弧度 radian 就可用于量纲为一的角度。','a dimensionless ratio；a dimensionless quantity；a dimensionless number。','dimensionless 不等于二维、扁平或没有体积。这里要把日常空间维度与物理量纲分开。',('The ratio of the two lengths is dimensionless.','这两个长度的比值是无量纲的。'),('Expressing strain as a dimensionless ratio makes comparisons easier.','把应变表示为无量纲比值，便于比较。'),sources=['https://www.nist.gov/pml/special-publication-811/nist-guide-si-chapter-7-rules-and-style-conventions-expressing-values']),
E('commensurate','/kəˈmensərət/','相称的；与……成比例的','把两边放到同一把尺子上：付出这么多，回报应该配得上。','借自晚期拉丁 commēnsūrātus；com-“共同” + mēnsūrāre“测量”。',A(C,'晚期拉丁 commēnsūrātus → 英语 commensurate','按共同尺度衡量 → 相应、相称的'),'pay commensurate with experience 是薪资与经验相称，不是两个数字必须相等。它关注大小、程度是否匹配，常用于工资、责任、投入和回报。','commensurate with experience；commensurate with the risk。','commensurable 更强调能否用共同标准或共同单位来量；commensurate 常强调比例合不合适。',('The salary should be commensurate with the responsibilities.','薪资应该与承担的职责相称。'),('The benefits were not commensurate with the effort required.','所得收益与需要付出的努力不相称。'),sources=['https://www.etymonline.com/word/commensurate']),
E('incommensurate','/ˌɪnkəˈmensərət/','不相称的；不成比例的','两边并非不能比较，而是摆在一起后明显不匹配。','in-“不” + commensurate。',A(C,'英语 commensurate → incommensurate','相称 → 不相称'),'a reward incommensurate with the effort 表示奖励与努力不匹配。它既可以是太少，也可以依上下文是太多，词本身不规定偏差方向。','incommensurate with the effort；incommensurate with the risk。','incommensurable 常说没有共同衡量标准；incommensurate 在常见用法中说比例不合适。',('The reward seemed incommensurate with the effort involved.','这份奖励似乎与付出的努力不相称。'),('The resources were incommensurate with the scale of the problem.','可用资源与问题的规模不匹配。'),sources=['https://www.merriam-webster.com/dictionary/incommensurate']),
E('commensurable','/kəˈmensərəbəl/','可用同一标准衡量的；可公度的','找一小段共同尺子，两段长度都能刚好由整数个小段拼成。','晚期拉丁 commēnsūrābilis，com-“共同” + mēnsūrābilis“可量的”。',A(C,'晚期拉丁 commēnsūrābilis → 英语 commensurable','具有共同度量 → 可公度、可同标准衡量'),'数学里两段长度可公度，表示长度之比是有理数。例如 2 米和 3 米，可共同用 1 米量成整数段。一般文章中也可指资料、价值等有足够共同标准可以比较。','commensurable quantities；commensurable with；a common measure。','2 和 3 没有大于 1 的共同整数因子，但仍可公度；不要把可公度与非互质混为一谈。',('Lengths of two metres and three metres are commensurable.','两米和三米的长度是可公度的。'),('The two scores are not directly commensurable because they use different scales.','这两个分数使用不同量表，不能直接按同一标准比较。'),sources=['https://www.merriam-webster.com/dictionary/commensurable']),
E('incommensurable','/ˌɪnkəˈmensərəbəl/','不可公度的；不能用同一尺度衡量的','再细分共同小尺子，也不能让两边都恰好是整数段；比喻时是缺少共同尺度。','经法语或直接从中世纪拉丁 incommēnsūrābilis 借入；in-“不” + commēnsūrābilis。',A(C,'中世纪拉丁 incommēnsūrābilis → 法语或直接借入英语 incommensurable','没有共同度量 → 不可公度、难按同标准比较'),'边长为 1 的正方形，对角线长 √2；两者之比无理，不能用一个共同长度单位同时量成整数段。谈价值观时，incommensurable 是不能轻易折算成同一种分数，不是宣称其中一边毫无价值。','incommensurable lengths；incommensurable values。','incomparable 常是无法比较或无与伦比；incommensurable 更着眼于缺少共同的量尺。',('The side and diagonal of a square are incommensurable.','正方形的边与对角线不可公度。'),('The essay treats freedom and comfort as incommensurable values.','这篇文章把自由与舒适视为无法用同一尺度衡量的价值。'),sources=['https://www.merriam-webster.com/dictionary/incommensurable']),
E('countermeasure','英 /ˈkaʊntəmeʒə/；美 /ˈkaʊntərmeʒər/','对策；应对措施；反制措施','对面出现一个问题，我方安排一个动作去抵消它。','counter-“对抗、抵消” + measure“措施”。',A(M,'英语 counter- + measure → countermeasure','应对威胁、纠正问题的措施'),'给系统加一道验证以应对攻击，就是 countermeasure；它不必是军事反击，也可以是预防性措施。这里 measure 用的是“办法”，不是测量动作。','a countermeasure against；effective countermeasures；develop countermeasures。','measurement 是测量；countermeasure 是处理风险或问题的手段，不是“反向测量”。',('The team introduced a countermeasure against repeated login attacks.','团队增加了一项应对反复登录攻击的措施。'),('Better drainage was proposed as a countermeasure against flooding.','有人提议改善排水，作为防洪对策。')),
E('mensuration','/ˌmensəˈreɪʃən/，也读 /ˌmenʃəˈreɪʃən/','测量；求长度、面积、体积的几何计算','给出形状和尺寸，再算周长、面积或能装多少。','接后期拉丁 mēnsūrātiō，经法语或直接从拉丁借入；再向前接 mēnsūrāre“测量”。',M[:1]+[['拉丁 mēnsūrāre → 后期拉丁 mēnsūrātiō → 法语或直接借入英语 mensuration','尺度、测量 → 测量以及几何量的计算']],'这个词比 measurement 专门，常见于数学教材，涵盖求面积、体积等。算圆柱容积可属于 mensuration，即使你是根据已知数值计算，没有亲手用量具测。','a mensuration problem；practical mensuration；mensuration formulas。','menstruation 是月经，接“月”的词族；mensuration 少了那个 t，接“量”的词族，两个词很容易看串。',('The chapter on mensuration covers areas and volumes.','关于几何测量的这一章讲面积与体积。'),('We solved a mensuration problem involving a cylindrical tank.','我们解了一道涉及圆柱形储罐的几何计算题。'),sources=['https://www.merriam-webster.com/dictionary/mensuration','https://www.etymonline.com/word/mensuration']),
E('remeasure','英 /ˌriːˈmeʒə/；美 /ˌriːˈmeʒər/','重新测量；再量一次','第一次可能不准，或者对象变了，于是把尺子再拿出来。','re-“再次” + measure。',A(MV,'英语 remeasure','再做一次测量'),'remeasure a room 是重新量房间；remeasure 可以为了核对，也可以为了观察变化，词本身不表示第一次一定出错。','remeasure the distance；remeasure carefully。','recalculate 是重新计算已有数字；remeasure 是重新取得测量结果，两步可能配合进行。',('Please remeasure the opening before we cut the panel.','切面板前，请重新量一下开口尺寸。'),('The researchers remeasured the trees after five years.','研究人员五年后重新测量了这些树。'),sources=['https://www.merriam-webster.com/dictionary/remeasure']),
]
ROOT=dict(id='C0725',meaning='测量、尺度、分寸',core='MENSUR = MEASURE',image='拿一把尺子量东西：量出大小是 measure，量各方向是 dimension；大得像量不尽是 immense；把两边放在同一尺度上看配不配，是 commensurate。',intro='拉丁 mētīrī 的意思是测量，分词 mēnsus 进入 mēnsūra 等词。到了英语，一条线保留 mens，如 immense、commensurate；另一条线经法语变成 measure。核心不止“量长度”，还包括用尺度判断程度、安排有分寸的行动。',forms='mens- / mensur- 来自拉丁分词与名词词干；measure 经过法语演变。dimension 的 di- 接 dis-，不表示二。immense 的 im- 是否定 in- 在 m 前的形式；commensurate 的 com- 表共同。',branches=[['量出大小与结果','measure, measuring, measured, measurement, measurable, remeasure, mensuration'],['大得难以量尽','immense, immensely, immensity, immeasurable, immeasurably'],['尺寸、方面与量纲','dimension, dimensional, dimensionality, dimensionless, multidimensional'],['共同尺度与相称程度','commensurate, incommensurate, commensurable, incommensurable'],['安排应对行动','countermeasure']],contrasts='measured 可以是说话有分寸，不只是被测过。immense 表非常大，不自动表示无限。commensurate 常问配不配，commensurable 常问能不能用共同尺度。dimensionless 在物理里不是“没有空间”。',practice='We measured the room twice, but the dimensions still surprised us. The work required immense patience and a budget commensurate with its scale.\n\n我们把房间量了两遍，尺寸还是让我们惊讶。这项工作需要极大的耐心，以及与规模相称的预算。',words=[w['word'] for w in W]+['multidimensional'])
